#!/usr/bin/env python3
"""Editable vector sources for the Endless Breach award and equipment library."""
from pathlib import Path
import math

OUT = Path(__file__).resolve().parents[1] / 'game/neon-arena/assets/survival/ui'
OUT.mkdir(parents=True, exist_ok=True)

def svg(name, title, body, color='#79eaff', secondary='#f7d67f', animated=False):
    animation = '<style>.orbit{transform-origin:64px 64px;animation:spin 8s linear infinite}.pulse{animation:pulse 2s ease-in-out infinite}@keyframes spin{to{transform:rotate(360deg)}}@keyframes pulse{50%{opacity:.45}}@media(prefers-reduced-motion:reduce){.orbit,.pulse{animation:none}}</style>' if animated else ''
    content=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" role="img" aria-labelledby="title"><title id="title">{title}</title><defs><linearGradient id="metal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#33596f"/><stop offset=".5" stop-color="#172735"/><stop offset="1" stop-color="#0b1420"/></linearGradient><linearGradient id="light" x1="0" y1="0" x2="1" y2="1"><stop stop-color="{color}"/><stop offset="1" stop-color="{secondary}"/></linearGradient><radialGradient id="glow"><stop stop-color="{color}" stop-opacity=".24"/><stop offset="1" stop-color="{color}" stop-opacity="0"/></radialGradient></defs>{animation}<circle cx="64" cy="64" r="62" fill="url(#glow)"/>{body}</svg>'''
    (OUT/name).write_text(content)

def badge(icon, color='#79eaff', secondary='#f7d67f', outer=True):
    frame='<path d="M64 8 105 25 108 73 93 100 64 120 35 100 20 73 23 25Z" fill="url(#metal)" stroke="url(#light)" stroke-width="2"/><path d="M64 16 98 31 100 70 88 94 64 112 40 94 28 70 30 31Z" fill="none" stroke="#7897a9" stroke-opacity=".3"/><path d="M19 51 9 58 19 65M109 51 119 58 109 65" fill="none" stroke="'+color+'" stroke-width="3"/><path d="m43 102 8 6m26-6-8 6" stroke="'+secondary+'" stroke-width="3"/>' if outer else ''
    return frame+icon

